<?php require dirname(__DIR__).'/includes/bootstrap.php';admin_required();$stats=$pdo->query("SELECT COUNT(*) total,COALESCE(SUM(invitation_views>0),0) viewed,COALESCE(SUM(invitation_views),0) views,COALESCE(SUM(rsvp_status<>'pending'),0) rsvps FROM guests")->fetch();$recent=$pdo->query('SELECT * FROM guests ORDER BY created_at DESC LIMIT 6')->fetchAll();$pageTitle='Dashboard';require '_header.php';?><section class="welcome"><div><span class="eyebrow">INVITATION OVERVIEW</span><h1>Namaste, <?=e($_SESSION['admin_name'])?></h1><p>Everything you need to share and track your wedding invitations.</p></div><a class="btn primary" href="guest-form.php">+ Add Guest</a></section><section class="stat-grid"><article><span>Total guests</span><b><?=number_format((int)$stats['total'])?></b></article><article><span>Guests viewed</span><b><?=number_format((int)$stats['viewed'])?></b></article><article><span>Total views</span><b><?=number_format((int)$stats['views'])?></b></article><article><span>RSVP responses</span><b><?=number_format((int)$stats['rsvps'])?></b></article></section><section class="panel"><div class="panel-head"><div><h2>Recent guests</h2><p>Latest personalized invitations</p></div><a href="guests.php">View all →</a></div><div class="table-wrap"><table><thead><tr><th>Guest</th><th>Status</th><th>Views</th><th>RSVP</th><th>Invitation</th></tr></thead><tbody><?php foreach($recent as $g):?><tr><td><b><?=e($g['name'])?></b><small><?=e($g['relation']?:'Guest')?></small></td><td><span class="status <?=$g['is_active']?'green':'gray'?>"><?=$g['is_active']?'Active':'Inactive'?></span></td><td><?=$g['invitation_views']?></td><td><span class="status"><?=e(ucfirst($g['rsvp_status']))?></span></td><td><a class="icon-btn" target="_blank" href="<?=base_url('invite/'.$g['slug'])?>">Open ↗</a></td></tr><?php endforeach;if(!$recent):?><tr><td colspan="5" class="empty">No guests yet. Add your first guest.</td></tr><?php endif;?></tbody></table></div></section><?php require '_footer.php';?>

